perguntas.enunciado:
Qual será o valor de x após a execução do código?

int x = 10;
x = x + 5;

Qual será a saída do código?

int x = 8;

if (x > 5) {
    printf("A");
} else {
    printf("B");
}

Qual será o valor de x após a execução do código?

int x = 10;
x--;

Qual será a saída do código?

int x = 4;

if (x > 2 && x < 10) {
    printf("Sim");
} else {
    printf("Nao");
}

Qual será a saída do código?

int x = 15;

if (x < 10 || x > 20) {
    printf("A");
} else {
    printf("B");
}

Qual será a saída do código?

int i;

for (i = 0; i < 5; i++) {
    printf("%d ", i);
}

Quantas vezes o printf() será executado?

int i;

for (i = 1; i <= 5; i++) {
    printf("Oi");
}

Qual será o valor de soma após a execução do código?

int soma = 0;

for (int i = 1; i <= 5; i++) {
    soma += i;
}

Qual será a saída do código?

int x = 10;
int y = 20;

if (x > y) {
    printf("X");
} else {
    printf("Y");
}

Qual será a saída do código?

int i;

for (i = 0; i < 5; i++) {
    if (i == 3) {
        break;
    }
    printf("%d ", i);
}

Qual será a saída do código?

int i;

for (i = 0; i < 5; i++) {
    if (i == 2) {
        continue;
    }
    printf("%d ", i);
}

Qual será o valor final de soma?

int soma = 0;

for (int i = 0; i < 3; i++) {
    for (int j = 0; j < 2; j++) {
        soma++;
    }
}
